import { signal } from '@pyreon/reactivity'
import { createRouter, useLoaderData, type LoaderData } from '@pyreon/router'

const signedIn = signal(false)
const loader = ({ params }: { params: Record<string, string> }) => fetchUser(params.id!)

const router = createRouter({
  mode: 'history',
  routes: [
    { path: '/user/:id', component: User, loader },
    { path: '/settings', component: Settings, beforeEnter: () => signedIn() || '/login' },
  ],
})

function User() {
  const user = useLoaderData<LoaderData<typeof loader>>()
  return <h1>{user.name}</h1>
}

