import { Show } from '@pyreon/core'
import { signal } from '@pyreon/reactivity'
import { useBlocker, useRouter } from '@pyreon/router'

// Mounted only while there are unsaved edits: a mounted blocker also makes
// closing the tab ask first.
const Unsaved = () => {
  useBlocker(() => true)
  return null
}

function Editor() {
  const dirty = signal(false)
  const router = useRouter()

  const leave = async () => {
    const result = await router.push('/')
    if (result === 'cancelled') alert('Save or discard your changes first.')
  }

  return (
    <div>
      <Show when={dirty}>
        <Unsaved />
      </Show>
      <textarea onInput={() => dirty.set(true)} />
      <button onClick={leave}>Done</button>
    </div>
  )
}
